def apply(repo: Path) -> None:
    app = repo / 'web' / 'app.js'
    css = repo / 'web' / 'app.css'
    if not app.exists() or not css.exists():
        raise PatchError('web/app.js or web/app.css missing')
    a = app.read_text(encoding='utf-8')
    c = css.read_text(encoding='utf-8')
    marker = '/* Smart Home v9.6 printer workspace */'
    if marker not in a:
        a += JS
    if marker not in c:
        c += CSS
    app.write_text(a, encoding='utf-8')
    css.write_text(c, encoding='utf-8')
    checks = ['v96InitPrinterWorkspace','WIDGET LIBRARY','TOUCHSCREEN PREVIEW','Automation rules','Unsaved changes','v96ApplyPreset','v96PrinterState','v96OpenPrinterTab']
    out = app.read_text(encoding='utf-8')
    for item in checks:
        if item not in out:
            raise PatchError('v9.6 portal contract missing: ' + item)

if __name__ == '__main__':
    ap = argparse.ArgumentParser()
    ap.add_argument('--repo', required=True)
    ap.add_argument('--apply', action='store_true')
    args = ap.parse_args()
    if not args.apply:
        raise SystemExit('Pass --apply')
    apply(Path(args.repo))
    print('Smart Home v9.6 printer workspace applied')
